// Источник: web-тест .qa/e2e/tests/admin/ad-04-prayer-admin-screen-cards.spec.ts, план .qa/e2e/specs/admin.md (24.5), кейс .qa/tests/admin/AD-04.
// Тикеты #a5decf4a (админка), #6a86f7ed9d38 (F-92: записи по קטע — карточка «הקראות הקטעים» вместо одной «הקלטת התפילה (MP3)»).
// Тексты: скриншоты 07.10 rec-F1/F4, upfail-final-summary-15 («הקראות הקטעים»: «מאושרות: N · ממתינות לאישור: N · לא תואמות לטקסט: N · בלי הקראה: N.
// ההעלאה והאישור נעשים במסך של כל קטע.»), rec-A1 (старой карточки MP3 молитвы нет), cdbc90a6-5 (история).
// Опора: «מה נדרש» (текст, утверждение, «מי אישר»), F-102 AC5 (кто и когда), F-92 AC1–4. Только просмотр: внутри экрана ничего не нажимать.
import { expect } from '@wdio/globals';
import { byText, byTextMatches, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { asAdmin, backToUser1, openAdminPrayer, scrollToMatch, sectionStatus, recordingSummary, cardRe } from '../_lib/admin.ts';

describe('Админка в приложении: экран молитвы', () => {
  afterEach(async () => { await toHome(); });

  it('AD-04 «ערבית · נוסח אשכנז»: карточки, статусы קטעים «מאושר · …»/«טקסט זמני, טרם אושר», сводка «הקראות הקטעים», история #a5decf4a #6a86f7ed9d38 @prod-safe', async () => {
    try {
      await asAdmin();
      // 1. Админка → «ערבית · נוסח אשכנז»: шапка и «N מתוך 15 קטעים מאושרים».
      await openAdminPrayer('ערבית', 'אשכנז');
      await expect(byTextMatches(cardRe('ערבית', 'אשכנז'))).toBeDisplayed();
      await expect(byTextMatches('\\d+ מתוך 15 קטעים מאושרים')).toBeDisplayed();

      // 2. Карточки: «הסבר וטיפ על התפילה» + «עריכת ההסבר והטיפ».
      await expect(await scrollToText('הסבר וטיפ על התפילה')).toBeDisplayed();
      await expect(await scrollToText('עריכת ההסבר והטיפ')).toBeDisplayed();

      // 3. «הקראות הקטעים» — сводка по записям; сумма = 15 קטעים; старой «הקלטת התפילה (MP3)» нет (rec-A1).
      const s = await recordingSummary();
      expect(s.approved + s.pending + s.notMatching + s.none).toBe(15);
      await expect(byText('הקלטת התפילה (MP3)')).not.toBeDisplayed();

      // 4. «אישור כל התפילה» (с «שם המאשר»), «קטעי התפילה» + «הוספת קטע».
      await expect(await scrollToText('אישור כל התפילה')).toBeDisplayed();
      await expect(await scrollToText('הוספת קטע')).toBeDisplayed();

      // 5. «המעריב ערבים» — «מאושר · <имя>, <дата>»; хотя бы один קטע «טקסט זמני, טרם אושר».
      const st = await sectionStatus('המעריב ערבים');
      expect(st).toMatch(/^מאושר\s*·\s*[^,]+,\s*\d{1,2}\.\d{1,2}\.\d{4}/);
      await expect(await scrollToText('טקסט זמני, טרם אושר')).toBeDisplayed();

      // 6. «היסטוריית אישורים»: запись «המעריב ערבים: … אושר על ידי …» (07.10: «הטקסט אושר כפי שהיה» / «נוסח חדש אושר»).
      await scrollToText('היסטוריית אישורים');
      await expect(await scrollToMatch('(?s)המעריב ערבים: (הטקסט אושר כפי שהיה|נוסח חדש אושר) על ידי .+')).toBeDisplayed();
    } finally {
      await backToUser1();
    }
  });
});
